param(\n  [string]$RepoRoot = (Get-Location).Path,\n  [string]$BundleZip = "",\n  [string]$DonorZip = "",\n  [string]$InstanceId = "default"\n)\n\n$ErrorActionPreference = "Stop"\nSet-Location $RepoRoot\n\n$PiCommand = if ([string]::IsNullOrWhiteSpace($env:STARBLOX_PI_COMMAND)) { "pi" } else { $env:STARBLOX_PI_COMMAND }\nif (-not (Get-Command $PiCommand -ErrorAction SilentlyContinue)) {\n  throw "StarBlox factory coding agent command is unavailable: $PiCommand"\n}\n\n& powershell -NoProfile -ExecutionPolicy Bypass -File "scripts\windows\same-day-studio-launch.ps1" -RepoRoot $RepoRoot -BundleZip $BundleZip -DonorZip $DonorZip -InstanceId $InstanceId\nif ($LASTEXITCODE -ne 0) {\n  throw "Studio staging launch/smoke verification failed."\n}\n\n$env:STARBLOX_STUDIO_INSTANCE_ID = $InstanceId\n\n& npm run same-day:pipeline -- --manifest "config/same-day/pipeline.example.json" --resume --stop-after wire-quest-mastery\nif ($LASTEXITCODE -ne 0) {\n  throw "Same-day adaptation pipeline blocked before quest/mastery verification."\n}\n\n& node "scripts/same-day-adaptation-receipt.mjs" --manifest "config/same-day/pipeline.example.json"\nif ($LASTEXITCODE -ne 0) {\n  throw "Adaptation receipt verification failed."\n}\n\n& npm run same-day:status -- --manifest "config/same-day/pipeline.example.json"\n\nWrite-Host ""\nWrite-Host "StarBlox donor adaptation + quest/mastery block: VERIFIED"\nWrite-Host "Target stage: wire-quest-mastery"\nWrite-Host "Receipt: artifacts\same-day-starblox\same-day-adaptation-receipt.json"\nWrite-Host "Publication remains disabled."\n